using System;

namespace IndustrialCodingStandards
{
    // 類別使用 PascalCase
    public class PlcController
    {
        // 常數使用全大寫 + 底線分隔
        public const int MAX_RETRY_COUNT = 3;
        public const int DEFAULT_BAUD_RATE = 9600;

        // 私有欄位使用底線前置 camelCase
        private string _stationName;
        private bool _isEmergencyStopped;

        // 建構子與公開屬性
        public PlcController(string stationName)
        {
            _stationName = stationName;
            _isEmergencyStopped = false;
        }

        // 公開方法使用動詞開頭的 PascalCase
        public bool ConnectPlc(string portName)
        {
            // 區域變數使用 camelCase
            int attemptCount = 0;
            bool isSuccess = false;

            while (attemptCount < MAX_RETRY_COUNT && !isSuccess)
            {
                attemptCount++;
                Console.WriteLine($"[{_stationName}] 嘗試連線至 {portName}，第 {attemptCount} 次...");
                isSuccess = true;
            }
            return isSuccess;
        }
    }
}

