using System;

namespace IndustrialBitwiseOperations
{
    internal class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine("=== 工控 PLC 暫存器位元解析實戰 ===");

            // 假設從 PLC D0 暫存器讀回狀態碼 0x0025 (二進位 0010 0101)
            // 代表 Y0=ON, Y2=ON, Y5=ON
            ushort plcStatusRegister = 0x0025;
            Console.WriteLine($"暫存器原始值: 0x{plcStatusRegister:X4} (二進位: {Convert.ToString(plcStatusRegister, 2).PadLeft(8, '0')})");

            // 檢查第 0 點 (Y0) 是否 ON
            bool isY0_On = (plcStatusRegister & (1 << 0)) != 0;
            // 檢查第 1 點 (Y1) 是否 ON
            bool isY1_On = (plcStatusRegister & (1 << 1)) != 0;
            // 檢查第 2 點 (Y2) 是否 ON
            bool isY2_On = (plcStatusRegister & (1 << 2)) != 0;

            Console.WriteLine($"Y0 (進料汽缸): {(isY0_On ? "[ON]" : "[OFF]")}");
            Console.WriteLine($"Y1 (排料汽缸): {(isY1_On ? "[ON]" : "[OFF]")}");
            Console.WriteLine($"Y2 (吸盤真空): {(isY2_On ? "[ON]" : "[OFF]")}");

            // 模擬將 Y1 強制開啟 (Bitwise OR)
            plcStatusRegister = (ushort)(plcStatusRegister | (1 << 1));
            Console.WriteLine($"強制設定 Y1 為 ON 後暫存器值: 0x{plcStatusRegister:X4}");
        }
    }
}

