namespace IndustrialLoopMechanisms
{
    internal class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine("=== 實戰示範：工控等待與看門狗逾時機制 ===");

            // 1. for 計數迴圈：自動送料 5 批
            for (int batch = 1; batch <= 5; batch++)
            {
                Console.WriteLine($"正在包裝第 {batch} 箱成品...");
            }

            Console.WriteLine("\r\n2. while 條件迴圈：模擬等待垂直汽缸下降到達 a1 極限端點...");
            bool cylinderDownSuccess = WaitForSensorWithTimeout(sensorTimeoutMs: 3000);

            if (cylinderDownSuccess)
            {
                Console.ForegroundColor = ConsoleColor.Green;
                Console.WriteLine("[動作完成] 汽缸順利到達下極限 a1，夾爪開始閉合！");
                Console.ResetColor();
            }
            else
            {
                Console.ForegroundColor = ConsoleColor.Red;
                Console.WriteLine("[硬體警報] 汽缸動作超時逾期 (未在時限內抵達 a1)，啟動急停保護！");
                Console.ResetColor();
            }
        }

        // 帶有看門狗超時保護的感測器等待函式
        static bool WaitForSensorWithTimeout(int sensorTimeoutMs)
        {
            Stopwatch sw = Stopwatch.StartNew();
            bool isSensorA1Reached = false;
            int mockTime = 0;

            while (!isSensorA1Reached)
            {
                // 檢測是否逾時
                if (sw.ElapsedMilliseconds > sensorTimeoutMs)
                {
                    return false; // 超時失敗
                }

                // 模擬讀取硬體訊號 (此處模擬在 1.5 秒時信號到位)
                Thread.Sleep(200);
                mockTime += 200;
                if (mockTime >= 1500)
                {
                    isSensorA1Reached = true;
                }
                Console.WriteLine($"等待信號中... 已經耗時 {sw.ElapsedMilliseconds} ms");
            }
            return true;
        }
    }
}

