namespace IndustrialStringAndOop
{
    // 建立機台站點物件導向藍圖
    public class ProductionStation
    {
        public int StationId { get; set; }
        public string StationName { get; set; }
        public double[] ToolWearValues { get; set; }

        public ProductionStation(int id, string name, int toolCount)
        {
            StationId = id;
            StationName = name;
            ToolWearValues = new double[toolCount];
        }

        // 解析通訊傳入的字串封包
        public void ParseTelemetry(string rawPacket)
        {
            // 例如封包格式: "#ST1:TOOL0=12.5;TOOL1=14.8;TOOL2=8.3*"
            if (rawPacket.StartsWith("#") && rawPacket.Contains("*"))
            {
                int start = rawPacket.IndexOf(":") + 1;
                int end = rawPacket.IndexOf("*");
                string payload = rawPacket.Substring(start, end - start);

                string[] toolPairs = payload.Split(';');
                for (int i = 0; i < toolPairs.Length && i < ToolWearValues.Length; i++)
                {
                    string[] kv = toolPairs[i].Split('=');
                    if (kv.Length == 2 && double.TryParse(kv[1], out double val))
                    {
                        ToolWearValues[i] = val;
                        Console.WriteLine($"[{StationName}] 刀具 #{i} 磨損量更新: {val} um");
                    }
                }
            }
        }
    }

    internal class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine("=== 工控字串處理與物件導向實務 ===");
            ProductionStation stationA = new ProductionStation(1, "研磨機台 A", 3);

            // 模擬接收串口回傳之封包
            string receivedSerial = "#ST1:TOOL0=12.5;TOOL1=14.8;TOOL2=8.3*";
            Console.WriteLine($"收到底層通訊封包: {receivedSerial}");
            stationA.ParseTelemetry(receivedSerial);
        }
    }
}

