namespace LAB_06_AsciiAndCheckSum
{
    public static class MitsubishiCheckSumHelper
    {
        // 計算三菱 FX 系列專用 ASCII CheckSum
        // 規則：從 CMD 開始至 ETX 為止的所有字元之 ASCII 數值加總，取最低 2 位十六進位碼
        public static string CalculateCheckSum(string commandPayloadWithEtx)
        {
            int sum = 0;
            byte[] asciiBytes = Encoding.ASCII.GetBytes(commandPayloadWithEtx);

            foreach (byte b in asciiBytes)
            {
                sum += b;
            }

            // 取最後一個 byte (0~255) 並轉為兩位大寫十六進位字串
            string checkSumHex = (sum & 0xFF).ToString("X2");
            return checkSumHex;
        }

        // 組裝完整封包：STX + Payload + ETX + CheckSum
        public static string BuildFullPacket(string payload)
        {
            char stx = (char)0x02; // 開頭
            char etx = (char)0x03; // 結束

            string contentToCalculate = payload + etx;
            string sum = CalculateCheckSum(contentToCalculate);

            return $"{stx}{contentToCalculate}{sum}";
        }
    }

    internal class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine("=== 三菱 PLC 通訊 CheckSum 演算法驗證 ===");

            // 讀取 Y0~Y17 範例 (投影片 Slide 185)
            // 命令 '0' + 元件群 '00A0' + 位元組數 '02'
            string payload = "000A002";
            string fullPacket = MitsubishiCheckSumHelper.BuildFullPacket(payload);

            Console.WriteLine($"原始有效指令負載: {payload}");
            Console.WriteLine($"組裝完成之完整通訊封包: {fullPacket.Replace("\x02", "<STX>").Replace("\x03", "<ETX>")}");
        }
    }
}

