            _plcPort = new SerialPort
            {
                PortName = "COM3",
                BaudRate = 9600,
                Parity = Parity.Even, // 三菱標準：偶同位
                DataBits = 7,         // 三菱標準：7 資料位
                StopBits = StopBits.One,
                ReadTimeout = 500,
                WriteTimeout = 500
            };
        }

        // 強制開啟 Y1 實體輸出 (例如驅動輸送帶電磁接觸器)
        private void btnForceY1_On_Click(object sender, EventArgs e)
        {
            // 投影片 Slide 173 範例: 強制 Y1 ON 封包
            // STX + '7' + '0105' + ETX + '00'
            char stx = (char)0x02;
            char etx = (char)0x03;
            string cmd = $"{stx}70105{etx}00";
            SendToPlc(cmd, "強制 Y1 ON");
        }

        // 強制關閉 Y1 實體輸出
        private void btnForceY1_Off_Click(object sender, EventArgs e)
        {
            // 投影片 Slide 173 範例: 強制 Y1 OFF 封包
            // STX + '8' + '0105' + ETX + '01'
            char stx = (char)0x02;
            char etx = (char)0x03;
            string cmd = $"{stx}80105{etx}01";
            SendToPlc(cmd, "強制 Y1 OFF");
        }

        private void SendToPlc(string packet, string logDesc)
        {
            try
            {
                if (!_plcPort.IsOpen) _plcPort.Open();
                _plcPort.Write(packet);
                txtLog.AppendText($"[TX] {logDesc} 封包已送出\r\n");
            }
            catch (Exception ex)
            {
                MessageBox.Show($"通訊錯誤: {ex.Message}");
            }
        }
    }
