namespace LAB_08_PlcMonitor
{
    public partial class FormPlcMonitor : Form
    {
        private Timer _pollTimer;
        private SerialPort _serialPort;
        private Button[] _yIndicators;

        public FormPlcMonitor()
        {
            InitializeComponent();
            InitHardware();
        }

        private void InitHardware()
        {
            _serialPort = new SerialPort("COM3", 9600, Parity.Even, 7, StopBits.One);

            // 建立 8 個燈號指示按鈕 (Y0~Y7)
            _yIndicators = new Button[8];
            for (int i = 0; i < 8; i++)
            {
                _yIndicators[i] = new Button
                {
                    Text = $"Y{i}",
                    Size = new Size(50, 50),
                    Location = new Point(30 + i * 55, 60),
                    BackColor = Color.Gray
                };
                this.Controls.Add(_yIndicators[i]);
            }

            // 設定每 200ms 輪詢一次
            _pollTimer = new Timer { Interval = 200 };
            _pollTimer.Tick += PollTimer_Tick;
            _pollTimer.Start();
        }

        private void PollTimer_Tick(object sender, EventArgs e)
        {
            // 暫停計時器避免重疊重入
            _pollTimer.Stop();
            try
            {
                if (!_serialPort.IsOpen) _serialPort.Open();

                // 投影片 Slide 181: 讀取 Y0~Y17 指令
                string cmdReadY = (char)0x02 + "000A002" + (char)0x03 + "66";
                _serialPort.Write(cmdReadY);

                // 讀取回傳
                System.Threading.Thread.Sleep(30); // 等待硬體回傳
                int bytes = _serialPort.BytesToRead;
                byte[] buff = new byte[bytes];
                _serialPort.Read(buff, 0, bytes);

                // 簡易解析點位 (以假資料模擬呈現)
                if (buff.Length >= 4)
                {
                    // 假設解析得 Y0=ON, Y2=ON
                    _yIndicators[0].BackColor = Color.LimeGreen;
                    _yIndicators[1].BackColor = Color.Gray;
                    _yIndicators[2].BackColor = Color.LimeGreen;
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"輪詢異常: {ex.Message}");
            }
            finally
            {
                _pollTimer.Start();
            }
        }
    }
}

