namespace LAB_09_04_WebServerDemo
{
    public partial class FormEmbeddedWebServer : Form
    {
        private TcpListener _httpListener;
        private Thread _serverThread;
        private bool _isRunning = false;

        public FormEmbeddedWebServer()
        {
            InitializeComponent();
            StartEmbeddedServer();
        }

        private void StartEmbeddedServer()
        {
            _isRunning = true;
            _httpListener = new TcpListener(IPAddress.Any, 8080);
            _httpListener.Start();
            _serverThread = new Thread(ListenForClients) { IsBackground = true };
            _serverThread.Start();
            lblServerStatus.Text = "內嵌 Web 伺服器運作中：http://localhost:8080/";
        }

        private void ListenForClients()
        {
            while (_isRunning)
            {
                try
                {
                    TcpClient client = _httpListener.AcceptTcpClient();
                    ThreadPool.QueueUserWorkItem(HandleClientRequest, client);
                }
                catch { break; }
            }
        }

        private void HandleClientRequest(object state)
        {
            TcpClient client = (TcpClient)state;
            using (NetworkStream stream = client.GetStream())
            {
                // 讀取 HTTP 請求標頭
                byte[] buffer = new byte[1024];
                stream.Read(buffer, 0, buffer.Length);

                // 產生即時產線 HTML 畫面 (帶有時間與即時機台狀態)
                string htmlResponse = $"<!DOCTYPE html><html><head><meta charset='utf-8'><title>遠端機台監控</title></head>" +
                                       "<body style='background:#0f172a;color:#fff;font-family:sans-serif;text-align:center;'>" +
                                       $"<h1>五股職訓局 - 機電AI_115-1期 遠端 HMI</h1>" +
                                       $"<h3>更新時間: {DateTime.Now:yyyy-MM-dd HH:mm:ss}</h3>" +
                                       "<p style='color:#22c55e;font-size:20px;'>● 產線運轉正常 (Continuous Running)</p>" +
                                       "<p>此網頁由上位機 C# 透過底層 Socket 自動驅動輸出</p>" +
                                       "</body></html>";

                byte[] bodyBytes = Encoding.UTF8.GetBytes(htmlResponse);
                string header = "HTTP/1.1 200 OK\r\n" +
                                "Content-Type: text/html; charset=utf-8\r\n" +
                                $"Content-Length: {bodyBytes.Length}\r\n" +
                                "Connection: close\r\n\r\n";
                byte[] headerBytes = Encoding.ASCII.GetBytes(header);

                stream.Write(headerBytes, 0, headerBytes.Length);
                stream.Write(bodyBytes, 0, bodyBytes.Length);
            }
            client.Close();
        }
    }
}
